import {
  createRoleAdministrationVersion,
  type RoleAdministrationVersionRecord,
  type RolePermissionSelection,
} from "../contracts/role-administration.js";
import { equalsPreset, rolePresetActions } from "../catalog/role-presets.js";
import type { RoleAdministrationOperation } from "./role-administration-service.js";

export interface RoleAdministrationDraftInput {
  /** Duplicate and Create: the new role's code (generated by the server, never typed). */
  readonly code?: string;
  readonly displayName: string;
  readonly description: string;
  readonly selections: readonly RolePermissionSelection[];
}

/**
 * WP-2423: builds the candidate next version for one role administration command from the role's
 * latest version (`current`), the version staff hold now (`effective`), the acting administrator
 * and the current Brand policy version. The service then authorizes, validates the transition and
 * commits it.
 */
export function planRoleAdministrationChange(input: {
  readonly operation: RoleAdministrationOperation;
  /** Null only for Create. */
  readonly current: RoleAdministrationVersionRecord | null;
  readonly effective?: RoleAdministrationVersionRecord | null;
  /** Create: where the new role lives. */
  readonly scope?: { readonly brandReference: string; readonly storeReference: string | null };
  readonly actorReference: string;
  readonly policyVersion: number;
  readonly changedAt: string;
  readonly reasonCode: string;
  readonly nextReference: () => string;
  readonly draft: RoleAdministrationDraftInput | null;
}): RoleAdministrationVersionRecord {
  const { current, draft } = input;
  const effective = input.effective ?? null;
  const fromDraft = () => {
    if (draft === null) throw new Error("ROLE_ADMIN_DRAFT_REQUIRED");
    return {
      displayName: draft.displayName,
      description: draft.description,
      selections: draft.selections.map((item) => ({ ...item })),
    };
  };
  const fresh = {
    roleType: "Custom",
    lifecycle: "Draft",
    sourcePolicyVersion: input.policyVersion,
    authoredByReference: input.actorReference,
    submittedByReference: null,
    approvedByReference: null,
    decisionEvidenceReference: null,
    approvalMode: "Independent",
    changedAt: input.changedAt,
    reasonCode: input.reasonCode,
  } as const;
  if (input.operation === "Create") {
    if (input.scope === undefined || draft?.code === undefined)
      throw new Error("ROLE_ADMIN_SCOPE_REQUIRED");
    return createRoleAdministrationVersion({
      ...fresh,
      ...fromDraft(),
      administrationReference: input.nextReference(),
      roleReference: input.nextReference(),
      version: 1,
      brandReference: input.scope.brandReference,
      storeReference: input.scope.storeReference,
      code: draft.code,
    });
  }
  if (current === null) throw new Error("ROLE_ADMIN_CURRENT_REQUIRED");
  const base = {
    ...current,
    version: current.version + 1,
    changedAt: input.changedAt,
    reasonCode: input.reasonCode,
    selections: current.selections.map((item) => ({ ...item })),
  };
  // After a withdrawn or rejected change, removing or bringing back works from what staff hold.
  const held =
    (current.lifecycle === "Rejected" || current.lifecycle === "Withdrawn") && effective !== null
      ? { ...effective, selections: effective.selections.map((item) => ({ ...item })) }
      : base;
  const heldState = {
    ...held,
    administrationReference: current.administrationReference,
    version: current.version + 1,
    changedAt: input.changedAt,
    reasonCode: input.reasonCode,
    sourcePolicyVersion: input.policyVersion,
  };
  switch (input.operation) {
    case "Duplicate":
      return createRoleAdministrationVersion({
        ...base,
        ...fresh,
        ...fromDraft(),
        administrationReference: input.nextReference(),
        roleReference: input.nextReference(),
        version: 1,
        code: draft?.code,
      });
    case "Revise":
    case "RestoreDefault":
      return createRoleAdministrationVersion({
        ...base,
        ...fresh,
        ...fromDraft(),
        version: current.version + 1,
      });
    case "SaveDraft":
      return createRoleAdministrationVersion({
        ...base,
        ...fromDraft(),
        authoredByReference: input.actorReference,
      });
    case "Submit":
      return createRoleAdministrationVersion({
        ...base,
        lifecycle: "InReview",
        submittedByReference: input.actorReference,
      });
    case "Approve":
    case "ApproveAlone":
      return createRoleAdministrationVersion({
        ...base,
        lifecycle: "Approved",
        approvedByReference: input.actorReference,
        decisionEvidenceReference: input.nextReference(),
        approvalMode: input.operation === "ApproveAlone" ? "SoleOperator" : "Independent",
      });
    case "Reject":
      return createRoleAdministrationVersion({
        ...base,
        lifecycle: "Rejected",
        decisionEvidenceReference: input.nextReference(),
      });
    case "Withdraw":
      return createRoleAdministrationVersion({
        ...base,
        lifecycle: "Withdrawn",
        approvedByReference: null,
        approvalMode: "Independent",
        decisionEvidenceReference: input.nextReference(),
      });
    case "Activate": {
      if (current.lifecycle === "Approved") {
        const preset = rolePresetActions(
          current.code,
          current.storeReference === null ? "Brand" : "Store",
        );
        const isPreset =
          preset !== null &&
          equalsPreset(
            current.selections.map((item) => item.action),
            preset,
          );
        return createRoleAdministrationVersion({
          ...base,
          lifecycle: "Active",
          roleType: isPreset ? "System" : "Custom",
          sourcePolicyVersion: input.policyVersion,
        });
      }
      return createRoleAdministrationVersion({ ...heldState, lifecycle: "Active" });
    }
    case "Deactivate":
      return createRoleAdministrationVersion({ ...heldState, lifecycle: "Deactivated" });
  }
}
